def pre(xs, target):
    for i in range(len(xs) - 1):
        if xs[i] >= xs[i + 1]:
            return False
    return True

def post(xs, target, result):
    found = -1
    for i in range(len(xs)):
        if xs[i] == target:
            found = i
    return result == found
